import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the transfer just made on the sheet the person went to (PERSON_TRANSFERRED ... from=),
 *  then that sheet's ROLLUP/TOTALS lines. */
public class RecordPersonArrived {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Transfer transfer, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Audit audit) {
        String user = by == null ? "" : by;
        String to = transfer.to();
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + user
                + " name=" + transfer.person().getName() + " from=" + transfer.person().getSheetId());
        Rollup after = Rollup.of(to, people, claims, rates, sheets, settings);
        for (String line : after.changesSince(transfer.toBefore(), to, user)) {
            audit.record(line);
        }
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The first step of every change: a viewer, and any change to an archived sheet, is refused before
 *  anything is read or written. */
public class RefuseViewer {
    public void refuse(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, RoleRepository roles,
            SheetRepository sheets) throws ViewerRefusedException, SheetArchivedException {
        if (sheets.isArchived(sheetId.trim())) {
            throw new SheetArchivedException("The sheet is archived");
        }
        if (Role.VIEWER.equals(roles.roleOf(sheetId.trim(), by == null ? "" : by))) {
            throw new ViewerRefusedException("A viewer may change nothing");
        }
    }
}
package net.officefloor.hq.app.setting;

/** The role a user name has on a sheet: clerk (any name without one), steward, or viewer (sees
 *  everything and may change nothing). */
public record Role(String sheetId, String user, String role) {
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";
    public static final String VIEWER = "viewer";
}
package net.officefloor.hq.app.setting;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class RoleRepository {

    private static final RowMapper<Role> ROW = (rs, n) ->
            new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;

    public RoleRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                ROW, sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them covers the sheet's
     *  today, else the one assigned (clerk when none was). */
    public String roleOf(String sheetId, String user) {
        return delegatorOf(sheetId, user) != null ? Role.STEWARD : assignedRoleOf(sheetId, user);
    }

    /** The user's own role on the sheet, delegations aside: clerk when none was assigned. */
    public String assignedRoleOf(String sheetId, String user) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                ROW, sheetId, user).stream().findFirst().map(Role::role).orElse(Role.CLERK);
    }

    /** The steward who delegated the steward role to the user by a delegation covering the sheet's
     *  today (the latest, when several do); null when none does. */
    public String delegatorOf(String sheetId, String user) {
        return jdbc.queryForList("SELECT d.delegated_by FROM delegation d JOIN sheet s ON s.id = d.sheet_id "
                + "WHERE d.sheet_id = ? AND d.user_name = ? AND d.from_date <= s.today AND s.today <= d.to_date "
                + "ORDER BY d.id DESC LIMIT 1", String.class, sheetId, user).stream().findFirst().orElse(null);
    }

    /** Assign (or replace) the user's role on the sheet. */
    public Role set(String sheetId, String user, String role, String by) {
        jdbc.update("DELETE FROM sheet_role WHERE sheet_id = ? AND user_name = ?", sheetId, user);
        jdbc.update("INSERT INTO sheet_role (sheet_id, user_name, role, set_by, set_at) "
                + "VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)", sheetId, user, role, by);
        return new Role(sheetId, user, role);
    }
}
# POST /api/sheets/{sheetId}/people/{personId}/transfer — a steward transfers the person to another
# sheet by id (to): they arrive there with their grades, terms, contact, aliases and claims (renumbered
# on the other sheet) and leave this one entirely (see TransferPerson). Anyone else, a retired person,
# this sheet's own id, or a name, alias or contact already on the other sheet, is refused.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonTransferred
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: arrive
arrive:
  class: net.officefloor.hq.app.person.RecordPersonArrived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson

