package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSetting;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The sheet's figures at one moment, as the screen shows them: each person's claimed and
 *  due-total (null: n/a; else at most the sheet's cap) and overdue-total, in the order they were added, and the
 *  sheet's claimed-total, due-total and overdue-total (these two leave out the single highest and
 *  lowest person's figure when three or more people have one). */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {

    /** A person's figures: their name, claimed, due-total (null: n/a) and overdue-total (the shown
     *  dues of their open claims past their due-by plus grace days on the sheet's today, n/a ones skipped). */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
        public boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed)
                    && (dueTotal == null ? other.dueTotal == null : dueTotal.equals(other.dueTotal))
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** The sheet's figures now. */
    public static Rollup of(String sheetId, PersonRepository people, ClaimRepository claims,
            RateRepository rates, SheetRepository sheets, SettingRepository settings) {
        List<Rate> sheetRates = rates.list(sheetId);
        DatedSetting floor = settings.floor(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LocalDate todayDate = sheets.today(sheetId);
        String today = todayDate.toString();
        Dues.Late late = settings.late(sheetId, todayDate);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person p : people.list(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean kept = false;
            for (Claim c : all) {
                if (c.getPersonId() != p.getId() || !p.countsLive(c)) continue;
                claimed = claimed.add(new BigDecimal(c.getAmount()));
                String grade = p.gradeOn(c.getDate());
                String pct = rateOn(sheetRates, grade, c.getDate());
                String d = Dues.shown(c, pct == null ? null : Dues.of(c.getAmount(), pct, late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
                kept |= c.getSettledDue() != null || c.isBound()
                        || (pct != null && (!grade.equals(p.getGrade()) || c.getDate().compareTo(today) <= 0));
                if (d != null) due = due.add(new BigDecimal(d));
                if (d != null && ClaimStatus.isOpen(c.getStatus()) && late.lateFrom(c).isBefore(todayDate)) {
                    overdue = overdue.add(new BigDecimal(d));
                }
            }
            boolean na = rateOn(sheetRates, p.getGrade(), today) == null && !kept;
            if (cap != null && due.compareTo(cap) > 0) due = cap.setScale(2);
            figures.put(p.getId(), new Figures(p.getName(), claimed.toPlainString(),
                    na ? null : due.toPlainString(), overdue.toPlainString()));
            claimedTotal = claimedTotal.add(claimed);
            if (!na) dues.add(due);
            overdues.add(overdue);
        }
        return new Rollup(figures, claimedTotal.toPlainString(), trimmedSum(dues).toPlainString(),
                trimmedSum(overdues).toPlainString());
    }

    /** The audit lines after a change from {@code before} to this: one ROLLUP per person whose
     *  figures moved (a new person counts as moved), then TOTALS when a sheet total moved. */
    public List<String> changesSince(Rollup before, String sheetId, String by) {
        String head = " sheet=" + sheetId + " by=" + by;
        List<String> lines = new ArrayList<>();
        people.forEach((id, now) -> {
            if (!now.sameAs(before.people.get(id))) {
                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
                        + " due-total=" + (now.dueTotal() == null ? "n/a" : now.dueTotal())
                        + " overdue-total=" + now.overdueTotal());
            }
        });
        if (!claimedTotal.equals(before.claimedTotal) || !dueTotal.equals(before.dueTotal)
                || !overdueTotal.equals(before.overdueTotal)) {
            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
                    + " overdue-total=" + overdueTotal);
        }
        return lines;
    }

    /** The grade's rate in force on the date (yyyy-MM-dd), inherited up the parent chain; null when none. */
    private static String rateOn(List<Rate> rates, String grade, String date) {
        Rate found = RateRepository.inForce(rates, grade, date);
        return found == null ? null : found.pct();
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        sorted.sort(BigDecimal::compareTo);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        BigDecimal total = zero();
        for (BigDecimal f : sorted) total = total.add(f);
        return total;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The number a claim gets when opened: while the sheet's period numbering is in force (its
 *  period-numbering-from is a date on or before the sheet's today) the next in the sequence of the
 *  period its due-by falls in ({@code <period>-<n>}; {@code X-<n>} in no period), else the sheet's next. */
public final class ClaimNumbers {
    private ClaimNumbers() {
    }

    public static String next(Claim claim, ClaimRepository claims, PeriodRepository periods,
            SettingRepository settings, SheetRepository sheets) {
        String sheetId = claim.getSheetId();
        LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            return claims.nextNumber(sheetId);
        }
        String period = periods.list(sheetId).stream().filter((p) -> p.contains(claim.getDueBy()))
                .map(Period::name).findFirst().orElse(null);
        return claims.nextPeriodNumber(sheetId, period);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.setting.RoleRepository;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The lines that only report figures: they never name a delegating steward. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    private final RoleRepository roles;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, RoleRepository roles) {
        this.file = Path.of(path);
        this.roles = roles;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user
     *  acting as a steward by delegation (the sheet's today inside its range) ends with
     *  {@code for=<the steward who delegated>}. */
    public synchronized void record(String entry) {
        entry = entry + delegatedFor(entry);
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** " for=<steward>" when the line's user acts by delegation on its sheet; else "". */
    private String delegatedFor(String entry) {
        String[] fields = entry.split(" ");
        if (FIGURES.contains(fields[0])) return "";
        String sheet = null;
        String by = null;
        for (String field : fields) {
            if (sheet == null && field.startsWith("sheet=")) sheet = field.substring("sheet=".length());
            else if (by == null && field.startsWith("by=")) by = field.substring("by=".length());
        }
        if (sheet == null || by == null || by.isEmpty()) return "";
        String steward = roles.delegatorOf(sheet, by);
        return steward == null ? "" : " for=" + steward;
    }

    /** The sheet's lines exactly as the file holds them, newest first. With a name (case and
     *  surrounding spaces ignored; blank: every line) only those carrying {@code name=<it>} or
     *  {@code person=<it>}. Reads the file; keeps nothing of its own. */
    public synchronized List<String> lines(String sheetId, String name) {
        if (!Files.exists(file)) return List.of();
        List<String> all;
        try {
            all = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        String sheetField = "sheet=" + sheetId;
        String who = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        for (String line : all) {
            if (!List.of(line.split(" ")).contains(sheetField)) continue;
            if (!who.isEmpty() && !about(line, who)) continue;
            found.add(line);
        }
        Collections.reverse(found);
        return found;
    }

    /** Whether the line carries name=<who> or person=<who> (who: trimmed, lower case). */
    private static boolean about(String line, String who) {
        String lower = " " + line.toLowerCase(Locale.ROOT) + " ";
        for (String key : List.of(" name=", " person=")) {
            int at = lower.indexOf(key);
            while (at >= 0) {
                int start = at + key.length();
                int end = start + who.length();
                if (lower.startsWith(who, start) && end < lower.length() && lower.charAt(end) == ' ') return true;
                at = lower.indexOf(key, at + 1);
            }
        }
        return false;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

